  const meshes = model.children.slice(start);
  if (!meshes.length) return;
  const group = new THREE.Group();
  group.name = name;
  meshes.forEach(mesh => group.add(mesh));
  const box = new THREE.Box3();
  group.children.forEach(mesh => { mesh.updateMatrix(); mesh.geometry.computeBoundingBox(); box.union(mesh.geometry.boundingBox.clone().applyMatrix4(mesh.matrix)); });
  const center = new THREE.Vector3(); box.getCenter(center);
  const offset = EXPLODE_OFFSETS[name] || {x:0,y:0,z:0};
  group.userData = { partName: name, label: PART_LABELS[name] || name, explode: offset, labelAnchor: center, restRotation: EXPLODE_ROTATIONS[name] || {x:0,y:0,z:0} };
  model.add(group);
  saberParts.push(group);
}
