```
if (!activityActive) return;
const n = saberParts.length;
let allDone = true;
const assembling = teardownPhase === 'assembling';
const frozen = teardownPhase === 'assembled' || teardownPhase === 'disassembled';
let total=0;
saberParts.forEach((group,index)=>{
  const delay = assembling ? (n-1-index)*TEARDOWN_STAGGER : index*TEARDOWN_STAGGER;
  let t = teardownPhase === 'assembled' ? 0 : teardownPhase === 'disassembled' ? 1 : Math.min(1, Math.max(0, (now - teardownStart - delay)/TEARDOWN_DURATION));
  if (frozen) t = teardownPhase==='disassembled' ? 1 : 0; // same as above
  if (!frozen && t < 1) allDone = false;
  const eased = t<.5 ? 4*t*t*t : 1-Math.pow(-2*t+2,3)/2;
  const p = assembling ? 1-eased : eased;
  total += p;
  const ex = group.userData.explode;
  const bob = p;
  group.position.set(ex.x*p+Math.cos(elapsed*1.1+index*1.7)*.022*p, ex.y*p+Math.sin(elapsed*1.6+index*1.3)*.045*p, ex.z*p+Math.sin(elapsed*.9+index*2.1)*.02*p);
  const rot=group.userData.restRotation;
  group.rotation.set(rot.x*p, rot.y*p+Math.sin(elapsed*.35+index)*.025*p, rot.z*p);
  const callout=group.userData.callout;
  if (callout) {
    const pos=group.userData.labelAnchor.clone().add(group.position);
    model.localToWorld(pos);
    pos.project(camera);
    const visible = p>.08 && pos.z<1;
    if (visible) {
      const x=(pos.x*.5+.5)*mount.clientWidth;
      const y=(-pos.y*.5+.5)*mount.clientHeight;
      callout.style.transform=`translate(${x}px,${y}px) translate(-50%,-50%)`;
      callout.style.opacity=String(Math.min(1,(p-.08)*4));
    } else callout.style.opacity='0';
  }
});
$('activityProgressFill').style.width = `${(total/n)*100}%`;
if (!frozen && allDone) {
  teardownPhase = assembling ? 'assembled' : 'disassembled';
  updateTeardownUI();
  playTone(assembling?760:640,.2);
}
