from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self): super().__init__(); self.stack=[]; self.errors=[]
    def handle_starttag(self,tag,attrs):
        if tag not in ('br','img','input','meta','link','hr','source'):
            self.stack.append(tag)
    def handle_endtag(self,tag):
        if not self.stack: self.errors.append('extra close '+tag); return
        if self.stack[-1]==tag: self.stack.pop()
        else:
            self.errors.append(f'mismatch {tag}, open {self.stack[-1]}')
            if tag in self.stack:
                while self.stack and self.stack[-1]!=tag: self.stack.pop()
                if self.stack: self.stack.pop()
p=P(); p.feed(open('index.html').read())
